typedef char V1 __attribute__((vector_size(1)));
unsigned size1(void){return sizeof(V1);}
unsigned align1(void){return _Alignof(V1);}
struct S1{char a;V1 b;char c;};
unsigned field1(void){return __builtin_offsetof(struct S1,b);}
unsigned record1(void){return sizeof(struct S1);}
